щин в каменных и бетонных конструкциях", "file_name": "gost_31937_safety_inspection.md"}'::jsonb, '{"applicable_defects": ["facade_crack"], "hazard_level": "structural_hazard", "source_title": "ГОСТ 31937-2011 Здания и сооружения. Правила обследования и мониторинга технического состояния", "chunk_size_chars": 550}'::jsonb, 'c020fdb5a72d7853435c7e5708848927d798f0f0288d3b30276535f4ddb97488') ON CONFLICT (source_id, chunk_index) DO UPDATE SET content = EXCLUDED.content, embedding = EXCLUDED.embedding, source_locator = EXCLUDED.source_locator, metadata = EXCLUDED.metadata, content_hash = EXCLUDED.content_hash, rate_id = EXCLUDED.rate_id;
INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 2, 'ГОСТ 31937-2011 Здания и сооружения. Правила обследования и мониторинга технического состояния. Пункт 5.3.3. Признаки прогрессирующих деформаций и аварийности
К признакам аварийного состояния относятся: сквозные трещины наружных и внутренних капитальных стен с раскрытием более 2 мм; вертикальные трещины с взаимным смещением плоскостей кромок; трещины в опорных зонах балок, ригелей и плит перекрытий; выпучивание или отклонение стен от вертикали. При фиксации указанных признаков объект переводится в категорию ограниченно-работоспособного или аварийного.', '[0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.081379,0.027126,0.000000,0.000000,0.081379,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.090421,0.000000,0.000000,0.000000,0.000000,0.081379,0.000000,0.117547,0.090421,0.000000,0.027126,0.027126,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.117547,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.027126,0.000000,0.000000,0.027126,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.180842,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.027126,0.090421,0.000000,0.000000,0.000000,0.000000,0.054253,0.000000,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.090421,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.027126,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.090421,0.000000,0.000000,0.081379,0.000000,0.000000,0.000000,0.000000,0.000000,0.054253,0.000000,0.000000,0.054253,0.027126,0.027126,0.00