INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 3, 'ГОСТ 31937-2011 Здания и сооружения. Правила обследования и мониторинга технического состояния. Пункт 5.3.4. Обязательный мониторинг и запрет на маскировку повреждений
При обнаружении трещин с признаками активности (раскрытия) категорически запрещается выполнять поверхностную заделку штукатурными смесями до установления причин трещинообразования. На трещины должны быть установлены маяки (пластинчатые или гипсовые) с фиксацией в журнале мониторинга сроком не менее 30 суток.', '[0.088066,0.000000,0.000000,0.000000,0.000000,0.058711,0.000000,0.000000,0.029355,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.088066,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.195703,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.058711,0.029355,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.097851,0.000000,0.000000,0.000000,0.000000,0.058711,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.088066,0.029355,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.058711,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.156562,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.058711,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.127207,0.000000,0.000000,0.000000,0.097851,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.097851,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.029355,0.029355,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.000000,0.000000,0.000000,0.029355,0.000000,0.000000,0.0