INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-PARKING-LEAK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 5, 'СП 250.1325800.2016 Здания остановочных пунктов и паркингов. Правила проектирования и ремонта. Пункт 8.1.2. Метод инъекционной гидроизоляции холодных и деформационных швов
Устранение активных протечек в швах бетонирования и сопряжениях плит перекрытий выполняется методом инъектирования через нагнетательные пакеры. В зону фильтрации под давлением до 15-20 МПа нагнетаются водореактивные полиуретановые смолы или быстротвердеющие акрилатные гели с низкой вязкостью, полимеризующиеся при контакте с водой и создающие эластичный гидробарьер.', '[0.000000,0.000000,0.000000,0.091014,0.000000,0.054609,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.091014,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.182029,0.054609,0.000000,0.000000,0.027304,0.027304,0.000000,0.000000,0.109217,0.054609,0.091014,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.091014,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.054609,0.000000,0.000000,0.000000,0.000000,0.054609,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.054609,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027304,0.091014,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.081913,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.109217,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.091014,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000,0.000000,0.027304,0.000000,0.000000,0.000000