-- Document: СП 29.13330.2011 Полы и облицовочные покрытия
INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-TILE-CHIP-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 8, 'СП 29.13330.2011 Полы и облицовочные покрытия. Пункт 7.4.1. Локальный ремонт и демонтаж поврежденной плитки
При наличии сколов, трещин или отслоений керамической плитки и керамогранита поврежденный элемент подлежит аккуратному демонтажу ручным или механизированным инструментом без передачи ударной нагрузки на соседние плитки. По периметру демонтируемой плитки предварительно расшиваются межплиточные швы на всю толщину плитки.', '[0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.095875,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.028763,0.000000,0.028763,0.000000,0.028763,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.095875,0.028763,0.095875,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.095875,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.095875,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057525,0.028763,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.028763,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057525,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028763,0.124638,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.095875,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057525,0.028763,0.028763,0.000000,0.095875,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0