INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-TILE-CHIP-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 9, 'СП 29.13330.2011 Полы и облицовочные покрытия. Пункт 7.4.2. Подготовка подстилающего основания
Основание под заменяемой плиткой тщательно расчищается от старого клеевого раствора или цементной постели до прочного монолитного слоя стяжки. Удаляются пыль, мусор и масляные загрязнения. Простукиванием контролируется прочность сцепления соседних плиток; при обнаружении глухого звука зона замены расширяется. Поверхность грунтуется адгезионным составом.', '[0.000000,0.000000,0.000000,0.110250,0.099225,0.000000,0.000000,0.143325,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.066150,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.110250,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.143325,0.000000,0.033075,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.000000,0.066150,0.033075,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.066150,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.110250,0.000000,0.000000,0.000000,0.000000,0.000000,0.066150,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.110250,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.110250,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.033075,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033075,0.000000,0.000000,0.066150,0.033075,0.000000,0.000000,0.033075,0.000000,0.000000,0.000000,0.