INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-TILE-CHIP-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 10, 'СП 29.13330.2011 Полы и облицовочные покрытия. Пункт 7.4.3. Технология укладки новой плитки
Укладка новой плитки выполняется на цементный плиточный клей повышенной адгезии (класс C1 для внутренних сухих зон, класс C2 для входных групп, крылец и влажных помещений). Толщина клеевого слоя составляет от 3 до 5 мм с обеспечением контактной площади клеевого раствора не менее 80% для внутренних помещений и не менее 95% для входных групп во избежание образования пустот и повторных сколов.', '[0.000000,0.000000,0.000000,0.095364,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.095364,0.028609,0.057218,0.000000,0.000000,0.057218,0.000000,0.057218,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.123973,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057218,0.095364,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.057218,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.057218,0.000000,0.000000,0.000000,0.000000,0.095364,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.028609,0.000000,0.000000,0.000000,0.000000,0.095364,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.085827,0.000000,0.000000,0.028609,0.028609,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.000000,0.000000,0.095364,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.028609,0.000000,0.000000,0.028609,0.000000,0.000000,0.028609,