INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-TILE-CHIP-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 11, 'СП 29.13330.2011 Полы и облицовочные покрытия. Пункт 7.4.4. Заполнение межплиточных швов
Швы между плитками очищаются от остатков выдавленного клея на глубину не менее половины толщины плитки. Заполнение швов производится влагостойкими затирочными смесями на цементной основе (CG2) или эпоксидными составами (RG) не ранее чем через 24 часа после завершения укладки плитки.', '[0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.033575,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.033575,0.000000,0.335746,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.067149,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.145490,0.145490,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.067149,0.000000,0.000000,0.111915,0.000000,0.000000,0.000000,0.000000,0.000000,0.111915,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.000000,0.000000,0.033575,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.033575,0.111915,0.000000,0.033575,0.033575,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.067149,0.111915,0.000000,0.000000,0.000000,0.111915,0.000000,0.000000,0.000000,0.067149,0.000000,0.033575,0.033575,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.