-- Document: СП 71.13330.2017 Изоляционные и отделочные покрытия
INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 12, 'СП 71.13330.2017 Изоляционные и отделочные покрытия. Пункт 7.2.1. Подготовка основания при ремонте штукатурных фасадов
Поверхности, подлежащие отделке и ремонту, должны быть очищены от пыли, грязи, масляных и битумных пятен, высолов и отслаивающихся слоев старой штукатурки. Перед нанесением ремонтных составов основание обеспыливается сжатым воздухом или промышленным пылесосом и обрабатывается проникающей полимерной грунтовкой для выравнивания впитывающей способности.', '[0.031065,0.031065,0.103551,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.103551,0.000000,0.031065,0.165681,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.103551,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.134616,0.000000,0.062130,0.000000,0.031065,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.103551,0.031065,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.031065,0.031065,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.062130,0.031065,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.031065,0.062130,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.062130,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.031065,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.062130,0.000000,0.000000,0.000000,0.000000,0.103551,0.000000,0.000000,0.000