INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 13, 'СП 71.13330.2017 Изоляционные и отделочные покрытия. Пункт 7.2.2. Технология расшивки и расчистки трещин
Трещины на оштукатуренных фасадах подлежат обязательной механической расшивке по всей длине на глубину не менее 10-15 мм с раскрытием кромок под углом 45 градусов (V-образная разделка). Внутренняя полость разделенной трещины тщательно очищается от крошки и обеспыливается с последующей обработкой грунтовочным составом глубокого проникновения.', '[0.060588,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.100979,0.000000,0.121175,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.100979,0.000000,0.030294,0.000000,0.000000,0.060588,0.100979,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.131273,0.030294,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.060588,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.100979,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.100979,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.131273,0.000000,0.000000,0.030294,0.000000,0.000000,0.000000,0.000000,0.000000,0.030294,0.000000,0.000000,0.000