INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 14, 'СП 71.13330.2017 Изоляционные и отделочные покрытия. Пункт 7.2.3. Заполнение полостей трещин ремонтными составами
