INSERT INTO normative_chunks (source_id, rate_id, chunk_index, content, embedding, embedding_model, source_locator, metadata, content_hash) VALUES ('d0000000-0000-4000-8000-000000000001', (SELECT rate_id FROM rates WHERE rate_code = 'DEMO-FACADE-CRACK-01' AND source_id = 'd0000000-0000-4000-8000-000000000001'), 15, 'СП 71.13330.2017 Изоляционные и отделочные покрытия. Пункт 7.2.13. Допустимые величины раскрытия трещин штукатурного слоя
Допустимая ширина раскрытия одиночных волосяных усадочных трещин на оштукатуренной поверхности без нарушения сцепления с основанием составляет не более 0.2 мм (устраняются финишным шпаклеванием). Трещины шириной от 0.2 до 2.0 мм классифицируются как эксплуатационные дефекты отделочного слоя и требуют технологической разделки, герметизации и локального восстановления окрасочного слоя. Трещины свыше 2.0 мм подлежат проверке на конструктивную глубину в несущей стене.', '[0.049147,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.000000,0.098295,0.024574,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.106486,0.081912,0.024574,0.000000,0.049147,0.000000,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.024574,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.081912,0.000000,0.000000,0.049147,0.000000,0.000000,0.000000,0.000000,0.049147,0.000000,0.024574,0.024574,0.000000,0.000000,0.000000,0.000000,0.081912,0.000000,0.000000,0.000000,0.000000,0.081912,0.000000,0.049147,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.024574,0.000000,0.024574,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.024574,0.000000,0.000000,0.000000,0.188398,0.000000,0.000000,0.000000,0.024574,0.000000,0.000000,0.0000